# The DDR's non-convertible domestic currency; no international reserve network.
ddr_mark = {
	picture = ddr_mark
	modifier = { political_power_gain = 0.05 }
	on_add = {
		log = "[GetDateText]: [Root.GetName]: Adopted ddr_mark domestic currency"
		hidden_effect = {
			set_variable = { no_foreign_reserve = 1 }
			calculate_reserve_roi_bonus = yes
		}
	}
	on_remove = {
		hidden_effect = {
			set_variable = { no_foreign_reserve = 0 }
			calculate_reserve_roi_bonus = yes
		}
	}
	cost = 50
	removal_cost = -1
	visible = {
		tag = DDR
		NOT = { date < 1968.1.1 }
		date < 1990.7.1
	}
	available = {
		tag = DDR
		NOT = { date < 1968.1.1 }
		date < 1990.7.1
		NOT = { has_country_flag = EU_joined_the_eurozone }
	}
	ai_will_do = {
		base = 0
		modifier = { add = 20 tag = DDR }
	}
}
